INSERT INTO feature VALUES('boot-data','runtime','A vector of bytes and a string buffer over the heap of the bootstrap','bootstrap','partial','ordinary',NULL,'The crate `gandr-boot-data` holds a vector of bytes in a block of the heap of `gandr-boot-alloc`: a capacity, a length, and one owner that gives the block back at its end, or by a release that gives the answer of the heap. A push writes after the last byte, an append copies a range of `gandr-boot-core` after it, and a cut keeps the first bytes. A growth doubles the capacity and uses each byte that the heap grants. A growth past the size of a layout, or one that the heap refuses, leaves the vector as it was. The string buffer is a vector of valid UTF-8 with one zero byte after the last byte: the check of UTF-8 of `gandr-boot-core` runs at each append and at each vector that becomes a buffer, and bytes that are not UTF-8 are rejected at the position of the first fault with the buffer unchanged. The buffer gives its bytes back as a vector with no copy. Each public function has no type parameter, and the crate is `no_std`. No twin in gandr replaces the crate (#7833).','boot-data','crates/boot-data/tests/vector.rs crates/boot-data/tests/string.rs','crate-tests','#7833');
